// Generated by AIArtEngine. Based on @deepseek-ai/dsh-headless.
// Persistent stdin worker: Cordis/MCP stay warm across turns; NDJSON commands on stdin.
import { createRequire } from 'node:module'
import { pathToFileURL } from 'node:url'
import { join, resolve, sep } from 'node:path'
import { readFileSync } from 'node:fs'
import { randomUUID } from 'node:crypto'
import { createInterface } from 'node:readline'

const PKG_ROOT = __DSH_NODE_MODULES_JSON__
const require = createRequire(pathToFileURL(join(PKG_ROOT, 'aiart-anchor.js')).href)
const imp = (id) => import(pathToFileURL(require.resolve(id)).href)

const { default: z } = await imp('@deepseek-ai/schemastery')
const { installModelSelection } = await imp('@deepseek-ai/dsh-agent')
const { createUserMessage } = await imp('@deepseek-ai/dsh-llm')
const { SessionId, SessionSeq } = await imp('@deepseek-ai/dsh-session')
const { defineTool } = await imp('@deepseek-ai/dsh-tools')

const name = 'aiart-headless-runner'
const inject = ['agentDefaultModel', 'agents', 'sessions']
const Config = z.object({ task: z.string().required() })

const REASONING_BEGIN = '===BEGIN_REASONING==='
const REASONING_END = '===END_REASONING==='
const TOOL_BEGIN = '===BEGIN_TOOL==='
const TOOL_END = '===END_TOOL==='
const ASK_USER_BEGIN = '===BEGIN_ASK_USER==='
const CONTEXT_BEGIN = '===BEGIN_CONTEXT==='
const PERSISTENT_TASK = '__AIART_PERSISTENT__'

const SUMMARY_KEYS = [
  'path',
  'pattern',
  'query',
  'name',
  'title',
  'description',
  'prompt',
  'command',
  'url',
  'file',
  'dir',
  'relativePath'
]

function summarizeToolArgs(raw) {
  if (typeof raw !== 'string' || raw === '') return ''
  try {
    const parsed = JSON.parse(raw)
    for (const key of SUMMARY_KEYS) {
      const value = parsed[key]
      if (typeof value === 'string' && value !== '')
        return value.length > 80 ? value.slice(0, 80) + '…' : value
    }
    const candidates = Object.values(parsed)
      .filter((v) => typeof v === 'string' && v !== '')
      .sort((a, b) => a.length - b.length)
    if (candidates.length) {
      const value = candidates[0]
      return value.length > 80 ? value.slice(0, 80) + '…' : value
    }
    const json = JSON.stringify(parsed)
    return json.length > 80 ? json.slice(0, 80) + '…' : json
  } catch {
    return raw.length > 80 ? raw.slice(0, 80) + '…' : raw
  }
}

function clipToolArgs(raw) {
  if (raw === undefined || raw === null || raw === '') return ''
  const text = typeof raw === 'string' ? raw : JSON.stringify(raw)
  if (typeof text !== 'string' || text === '') return ''
  return text.length > 4000 ? text.slice(0, 4000) + '…' : text
}

function summarize(session, firstSeq) {
  let started = false
  let text = ''
  let reason
  for (let seq = firstSeq; seq <= session.seq; seq++) {
    const event = session.eventAt(SessionSeq(seq))
    if (event === void 0) continue
    if (event.type === 'turn/start') {
      started = true
      continue
    }
    if (!started) continue
    if (event.type === 'assistant/message') {
      const content = event.data?.message?.content ?? []
      const joined = content
        .filter((block) => block.type === 'text')
        .map((block) => block.text)
        .join('')
      if (joined !== '') text = joined
    }
    if (event.type === 'turn/end') reason = event.data.reason
  }
  return { text, reason }
}

function imageMediaType(path) {
  const m = /\.([a-z0-9]+)$/i.exec(path)
  const ext = m ? m[1].toLowerCase() : ''
  if (ext === 'png') return 'image/png'
  if (ext === 'jpg' || ext === 'jpeg') return 'image/jpeg'
  if (ext === 'webp') return 'image/webp'
  if (ext === 'gif') return 'image/gif'
  return null
}

const MAX_USER_IMAGES = 20

async function buildUserContent(task, attachments, io) {
  const blocks = []
  const cwd = process.cwd()
  let last = 0
  let imageCount = 0
  const refRe = /@(?:(image:)\s*)?([^\s@]+)/g
  let m
  while ((m = refRe.exec(task)) !== null) {
    const prefix = m[1] ?? ''
    const raw = m[2]
    const path = raw.replace(/\\/g, '/')
    const before = task.slice(last, m.index)
    last = m.index + m[0].length
    const mediaType = imageMediaType(path)
    const canAttach = mediaType !== null && imageCount < MAX_USER_IMAGES && attachments?.saveImage
    if (!canAttach) {
      if (before !== '') blocks.push({ type: 'text', text: before })
      blocks.push({ type: 'text', text: '@' + prefix + raw })
      continue
    }
    imageCount += 1
    if (before !== '') blocks.push({ type: 'text', text: before })
    try {
      const abs = resolve(cwd, path)
      if (!abs.startsWith(cwd + sep)) throw new Error('path escapes workspace')
      const buf = readFileSync(abs)
      const attachment = await attachments.saveImage({
        data: buf,
        mediaType,
        name: path.split('/').pop()
      })
      blocks.push({ type: 'image', attachment })
      blocks.push({ type: 'text', text: '@' + prefix + raw })
    } catch (error) {
      io.stderr.write(
        '[aiart-runner] image attach failed ' +
          raw +
          ': ' +
          (error instanceof Error ? error.message : String(error)) +
          '\n'
      )
      blocks.push({ type: 'text', text: '@' + prefix + raw })
    }
  }
  const rest = task.slice(last)
  if (rest !== '') blocks.push({ type: 'text', text: rest })
  return blocks
}

function modePreamble(mode) {
  if (mode === 'ask') {
    return (
      '[AIArtEngine panel mode: Ask]\n' +
      'Answer in text only. Do not call tools or modify files.\n\n'
    )
  }
  if (mode === 'plan') {
    return (
      '[AIArtEngine panel mode: Plan]\n' +
      'First outline a concise plan, then call ask_user_question to confirm before any write/generate tools.\n\n'
    )
  }
  return '[AIArtEngine panel mode: Craft]\nPrefer MCP tools to complete the request.\n\n'
}

function registerAskUserTool(ctx, io, getMode, getRunId) {
  const userQuestions = ctx.get('userQuestions')
  const toolsRegistry = ctx.get('tools')
  if (!toolsRegistry?.register) return

  const answerAskUserQuestion = async (request) => {
    const first = request?.questions?.[0]
    if (!first) return { answers: [] }
    try {
      const runId = getRunId() || 'run'
      const requestId = 'harness:' + runId + ':' + randomUUID()
      const answerFile = join(
        process.env.AIART_ASK_DIR || '',
        'aiart-ask-' + requestId.replace(/[^a-zA-Z0-9_-]/g, '-') + '.json'
      )
      io.stdout.write(
        ASK_USER_BEGIN +
          JSON.stringify({
            requestId,
            questionId: first.id,
            question: first.question,
            ...(first.header ? { hint: first.header } : {}),
            options: (first.options ?? []).map((option) => option.label),
            answerFile
          }) +
          '\n'
      )
      const deadline = Date.now() + 5 * 60 * 1000
      while (Date.now() < deadline) {
        if (request?.signal?.aborted) return { answers: [{ id: first.id, selected: [] }] }
        try {
          const raw = readFileSync(answerFile, 'utf8')
          return JSON.parse(raw)
        } catch {
          /* waiting */
        }
        await new Promise((resolve) => setTimeout(resolve, 250))
      }
      return { answers: [{ id: first.id, selected: [] }] }
    } catch (error) {
      io.stderr.write(
        '[aiart-runner] ask-user answerer error: ' +
          (error instanceof Error ? error.message : String(error)) +
          '\n'
      )
      return { answers: [{ id: first.id, selected: [] }] }
    }
  }

  toolsRegistry.register(
    defineTool({
      name: 'ask_user_question',
      description:
        'Ask the user a concise question when you need confirmation, a choice, or missing information before proceeding. Send one or more questions, each with a stable id that will be echoed in the answer.',
      parameters: {
        questions: {
          type: 'array',
          required: true,
          description: 'Questions to ask the user before continuing.',
          items: {
            type: 'object',
            additionalProperties: true,
            properties: {
              id: {
                type: 'string',
                required: true,
                description: 'Stable id for this question; echoed in the answer.'
              },
              question: {
                type: 'string',
                required: true,
                description: 'The specific question to ask the user.'
              },
              header: {
                type: 'string',
                description:
                  'Optional short heading for the question, such as "Confirm" or "Choose Mode".'
              },
              options: {
                type: 'array',
                description:
                  'Optional choices to show the user. If you recommend one, put it first and append "(Recommended)" to that label.',
                items: {
                  type: 'object',
                  additionalProperties: true,
                  properties: {
                    label: {
                      type: 'string',
                      required: true,
                      description: 'Short user-facing option label.'
                    },
                    description: {
                      type: 'string',
                      description: 'One sentence explaining the tradeoff or impact.'
                    }
                  }
                }
              },
              multi_select: {
                type: 'boolean',
                description: 'Whether the user may select more than one option. Defaults to false.'
              }
            }
          }
        }
      },
      output: {
        schema: {
          type: 'object',
          additionalProperties: false,
          properties: {
            answers: {
              type: 'array',
              required: true,
              items: {
                type: 'object',
                additionalProperties: false,
                properties: {
                  id: { type: 'string', required: true },
                  selected: { type: 'array', required: true, items: { type: 'string' } },
                  custom: { type: 'string' }
                }
              }
            }
          }
        },
        render: (_args, value) => [{ type: 'text', text: JSON.stringify(value) }]
      },
      async execute(args, exec) {
        if (getMode() === 'ask') {
          throw new Error('Ask mode does not allow ask_user_question; answer in text only.')
        }
        if (!userQuestions) throw new Error('userQuestions service is unavailable')
        const response = await userQuestions.ask({
          questions: args.questions.map((question) => ({
            id: question.id,
            question: question.question,
            ...(question.header !== undefined ? { header: question.header } : {}),
            ...(question.options !== undefined ? { options: question.options } : {}),
            ...(question.multi_select !== undefined ? { multiSelect: question.multi_select } : {})
          })),
          ...(exec.agent !== undefined ? { agent: exec.agent } : {}),
          signal: exec.signal
        })
        return {
          answers: response.answers.map((answer) => ({
            id: answer.id,
            selected: [...answer.selected],
            ...(answer.custom !== undefined ? { custom: answer.custom } : {})
          }))
        }
      }
    })
  )

  return answerAskUserQuestion
}

/** Drop a cached agent and release its session write handle (flush alone is not enough). */
async function releaseAgentSlot(agentSlot) {
  const handle = agentSlot.handle
  agentSlot.handle = undefined
  agentSlot.sessionId = ''
  agentSlot.model = ''
  agentSlot.provider = ''
  if (!handle?.dispose) return
  try {
    await handle.dispose()
  } catch {
    /* ignore — next create/resume must not be blocked by a leaked write lease */
  }
}

async function runOneTurn(ctx, io, opts) {
  const {
    task,
    sessionId: rawSessionId,
    mode,
    runId,
    selection,
    answerAskUserQuestion,
    agentSlot
  } = opts
  const agents = ctx.get('agents')
  const sessions = ctx.get('sessions')
  if (agents === void 0 || sessions === void 0) throw new Error('agents/sessions unavailable')

  const sessionId = (rawSessionId || '').trim() || 'session-' + randomUUID()
  const agentOptions = { provider: selection.provider, model: selection.model }
  const setup = (agentCtx) => {
    installModelSelection(agentCtx, {
      current: selection,
      assembled: void 0
    })
    agentCtx.on('user-questions/request', (request) =>
      answerAskUserQuestion(request).catch((error) => {
        io.stderr.write(
          '[aiart-runner] ask-user answerer failed: ' +
            (error instanceof Error ? error.message : String(error)) +
            '\n'
        )
        const first = request?.questions?.[0]
        return { answers: first ? [{ id: first.id, selected: [] }] : [] }
      })
    )
  }

  let agent = agentSlot.handle?.agent
  const sameSession = agentSlot.sessionId === sessionId
  const sameModel =
    agent && agentSlot.model === selection.model && agentSlot.provider === selection.provider

  if (agent && (!sameSession || !sameModel)) {
    try {
      await sessions.flush(agent.session)
    } catch {
      /* ignore */
    }
    await releaseAgentSlot(agentSlot)
    agent = undefined
  }

  if (agent === undefined) {
    const persistence = ctx.get('sessionPersistence')
    const hasSessionId = !!(rawSessionId || '').trim()
    if (persistence !== void 0 && hasSessionId) {
      const exists =
        typeof persistence.stat === 'function'
          ? (await persistence.stat(SessionId(sessionId))) !== void 0
          : (await persistence.list()).some(
              (entry) => (entry?.id ?? entry?.sessionId ?? entry?.header?.id) === sessionId
            )
      if (exists) {
        try {
          const resumed = await agents.resume({
            resumeSessionId: sessionId,
            agentOptions,
            setup
          })
          agentSlot.handle = resumed
          agent = resumed.agent
          io.stderr.write('[aiart-runner] resumed session: ' + sessionId + '\n')
        } catch (error) {
          // Same-process leak recovery: agent still registered → reuse instead of resume
          const live =
            typeof agents.get === 'function' ? agents.get(SessionId(sessionId)) : undefined
          const owned =
            error instanceof Error && /already owned by an active write handle/i.test(error.message)
          if (owned && live) {
            agentSlot.handle = {
              agent: live,
              // Best-effort teardown: disposing the agent scope runs the loop's
              // tracked disposer, which closes the persistence write handle.
              dispose: async () => {
                try {
                  if (typeof live.cancel === 'function') live.cancel({ kind: 'disposed' })
                } catch {
                  /* ignore */
                }
                try {
                  if (typeof live.whenIdle === 'function') await live.whenIdle()
                } catch {
                  /* ignore */
                }
                try {
                  if (live.scope && typeof live.scope.dispose === 'function') {
                    await live.scope.dispose()
                  }
                } catch {
                  /* ignore */
                }
              }
            }
            agent = live
            io.stderr.write('[aiart-runner] reused live session: ' + sessionId + '\n')
          } else {
            io.stderr.write(
              '[aiart-runner] resume failed: ' +
                (error instanceof Error ? error.message : String(error)) +
                '\n'
            )
            throw error
          }
        }
      }
    }
    if (agent === undefined) {
      const created = await agents.create({
        sessionId: SessionId(sessionId),
        meta: { cwd: process.cwd() },
        agentOptions,
        setup
      })
      agentSlot.handle = created
      agent = created.agent
      if (hasSessionId) io.stderr.write('[aiart-runner] created session: ' + sessionId + '\n')
    }
    agentSlot.sessionId = sessionId
    agentSlot.model = selection.model
    agentSlot.provider = selection.provider
  }

  await agent.whenIdle()
  const firstSeq = agent.session.seq

  let lastSeq = firstSeq
  let inReasoning = false
  let streamedText = false
  const pendingTools = new Map()
  const closeReasoning = () => {
    if (inReasoning) {
      inReasoning = false
      io.stdout.write('\n' + REASONING_END + '\n')
    }
  }
  const offStream = ctx.on('agent/assistant-stream', ({ agent: subject, frame }) => {
    if (subject !== agent) return
    if (frame.type !== 'chunk') {
      closeReasoning()
      return
    }
    const chunk = frame.chunk
    if (chunk === void 0) return
    switch (chunk.type) {
      case 'reasoning-delta':
        if (chunk.text === '') return
        if (!inReasoning) {
          inReasoning = true
          io.stdout.write(REASONING_BEGIN + '\n')
        }
        io.stdout.write(chunk.text)
        return
      case 'block-start':
        if (chunk.blockType !== 'reasoning') closeReasoning()
        return
      case 'block-end':
        if (chunk.block === void 0 || chunk.block.type !== 'reasoning') closeReasoning()
        return
      case 'text-delta':
        if (chunk.text === '') return
        streamedText = true
        closeReasoning()
        io.stdout.write(chunk.text)
        return
      case 'usage':
        return
      default:
        closeReasoning()
    }
  })
  const flushEvents = () => {
    for (; lastSeq < agent.session.seq; lastSeq++) {
      const event = agent.session.eventAt(SessionSeq(lastSeq))
      if (event === void 0) continue
      if (event.type === 'tool/call') {
        const callId = event.data?.callId
        if (typeof callId === 'string' && !pendingTools.has(callId)) {
          const toolName = event.data?.name || 'tool'
          pendingTools.set(callId, toolName)
          closeReasoning()
          io.stdout.write(
            '\n' +
              TOOL_BEGIN +
              JSON.stringify({
                name: toolName,
                callId,
                detail: summarizeToolArgs(event.data?.arguments),
                args: clipToolArgs(event.data?.arguments)
              }) +
              '\n'
          )
        }
        continue
      }
      if (event.type === 'tool/result') {
        const callId = event.data?.message?.source?.callId
        if (typeof callId === 'string') {
          const toolName = pendingTools.get(callId) || 'tool'
          pendingTools.delete(callId)
          io.stdout.write('\n' + TOOL_END + JSON.stringify({ name: toolName, callId }) + '\n')
        }
        continue
      }
      if (event.type === 'assistant/message' && event.data?.usage) {
        const usage = event.data.usage
        if (typeof usage.inputTokens === 'number' && usage.inputTokens >= 0) {
          closeReasoning()
          io.stdout.write('\n' + CONTEXT_BEGIN + JSON.stringify(usage) + '\n')
        }
      }
    }
  }

  const timer = setInterval(flushEvents, 30)
  try {
    const fullTask = modePreamble(mode) + task
    const userContent = await buildUserContent(fullTask, ctx.get('attachments'), io)
    agent.followup(
      createUserMessage({
        content: userContent,
        source: { kind: 'user' }
      })
    )
    await agent.whenIdle()
  } finally {
    clearInterval(timer)
    offStream()
  }
  flushEvents()
  if (inReasoning) io.stdout.write('\n' + REASONING_END + '\n')
  try {
    await sessions.flush(agent.session)
  } catch (error) {
    io.stderr.write(
      '[aiart-runner] session flush failed: ' +
        (error instanceof Error ? error.message : String(error)) +
        '\n'
    )
  }
  const outcome = summarize(agent.session, firstSeq)
  if (!streamedText && outcome.text) io.stdout.write(outcome.text + '\n')
  if (outcome.reason?.kind === 'error') {
    io.stderr.write(
      'dsh: ' + outcome.reason.error.code + ': ' + outcome.reason.error.message + '\n'
    )
    throw new Error(outcome.reason.error.message || outcome.reason.error.code || 'turn error')
  }
  return outcome
}

async function runPersistent(ctx, io) {
  let currentMode = (process.env.AIART_MODE || 'craft').trim() || 'craft'
  let currentRunId = process.env.AIART_RUN_ID || 'run'
  let forcedSelection = null
  const agentSlot = { handle: undefined, sessionId: '', model: '', provider: '' }

  const answerAskUserQuestion = registerAskUserTool(
    ctx,
    io,
    () => currentMode,
    () => currentRunId
  )

  await ctx.get('loader')?.await()
  const defaultModel = ctx.get('agentDefaultModel')
  const agents = ctx.get('agents')
  const sessions = ctx.get('sessions')
  if (agents === void 0 || defaultModel === void 0 || sessions === void 0) {
    throw new Error('required services missing')
  }

  io.stderr.write('[aiart-runner] ready\n')

  const rl = createInterface({ input: process.stdin, crlfDelay: Infinity })
  for await (const line of rl) {
    const trimmed = line.trim()
    if (!trimmed) continue
    let msg
    try {
      msg = JSON.parse(trimmed)
    } catch {
      io.stderr.write('[aiart-runner] ignore non-json stdin line\n')
      continue
    }
    const op = msg?.op
    if (op === 'shutdown') {
      await releaseAgentSlot(agentSlot)
      rl.close()
      io.exit(0)
      return
    }
    if (op === 'set_model') {
      const modelId = typeof msg.modelId === 'string' ? msg.modelId.trim() : ''
      if (!modelId) {
        io.stderr.write(
          '[aiart-runner] model_set ' +
            JSON.stringify({ ok: false, error: 'missing modelId' }) +
            '\n'
        )
        continue
      }
      const cur = defaultModel.currentSelection()
      forcedSelection = {
        provider: cur?.provider || 'deepseek-official',
        model: modelId
      }
      // Must dispose so the session write lease is released before next resume
      await releaseAgentSlot(agentSlot)
      io.stderr.write('[aiart-runner] model_set ' + JSON.stringify({ ok: true, modelId }) + '\n')
      continue
    }
    if (op === 'prompt') {
      const task = typeof msg.task === 'string' ? msg.task : ''
      if (!task.trim()) {
        io.stderr.write(
          '[aiart-runner] turn_done ' + JSON.stringify({ ok: false, error: 'empty task' }) + '\n'
        )
        continue
      }
      currentMode = typeof msg.mode === 'string' && msg.mode ? msg.mode : currentMode
      currentRunId = typeof msg.runId === 'string' && msg.runId ? msg.runId : currentRunId
      const selection = forcedSelection || defaultModel.currentSelection()
      io.stderr.write(
        '[aiart-runner] prompt_start ' +
          JSON.stringify({
            runId: currentRunId,
            mode: currentMode,
            model: selection?.model || ''
          }) +
          '\n'
      )
      try {
        await runOneTurn(ctx, io, {
          task,
          sessionId: typeof msg.sessionId === 'string' ? msg.sessionId : '',
          mode: currentMode,
          runId: currentRunId,
          selection,
          answerAskUserQuestion,
          agentSlot
        })
        io.stderr.write('[aiart-runner] turn_done ' + JSON.stringify({ ok: true }) + '\n')
      } catch (error) {
        io.stderr.write(
          '[aiart-runner] turn_done ' +
            JSON.stringify({
              ok: false,
              error: error instanceof Error ? error.message : String(error)
            }) +
            '\n'
        )
      }
      continue
    }
    io.stderr.write('[aiart-runner] unknown op: ' + String(op) + '\n')
  }
  await releaseAgentSlot(agentSlot)
  io.exit(0)
}

/** One-shot path (npx / legacy): single task then exit */
async function runOnce(ctx, task, io) {
  const mode = (process.env.AIART_MODE || 'craft').trim() || 'craft'
  const runId = process.env.AIART_RUN_ID || 'run'
  // Ask：不注册 ask_user_question（与历史 one-shot 行为一致）
  const answerAskUserQuestion =
    mode === 'ask'
      ? async () => ({ answers: [] })
      : registerAskUserTool(
          ctx,
          io,
          () => mode,
          () => runId
        )
  await ctx.get('loader')?.await()
  const defaultModel = ctx.get('agentDefaultModel')
  if (defaultModel === void 0) return
  const agentSlot = { handle: undefined, sessionId: '', model: '', provider: '' }
  const selection = defaultModel.currentSelection()
  const outcome = await runOneTurn(ctx, io, {
    task,
    sessionId: (process.env.AIART_SESSION_ID || '').trim(),
    mode,
    runId,
    selection,
    answerAskUserQuestion,
    agentSlot
  })
  await releaseAgentSlot(agentSlot)
  io.exit(outcome.reason?.kind === 'completed' ? 0 : 1)
}

function apply(ctx, config) {
  const exit = ctx.get('appExit')
  if (exit === void 0) {
    throw new Error(
      'aiart-headless-runner: the launcher must provide ctx.appExit before the tree mounts'
    )
  }
  const io = { stdout: process.stdout, stderr: process.stderr, exit }
  const task = config.task
  const persistent = process.env.AIART_PERSISTENT === '1' || task === PERSISTENT_TASK || task === ''
  const run = persistent ? runPersistent(ctx, io) : runOnce(ctx, task, io)
  run.catch((error) => {
    io.stderr.write('dsh: ' + (error instanceof Error ? error.message : String(error)) + '\n')
    io.exit(1)
  })
}

export { Config, apply, inject, name }
